import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Profession System","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/professions/profession-system.md","filePath":"game-design/professions/profession-system.md"}'),r={name:"game-design/professions/profession-system.md"};function s(o,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="profession-system" tabindex="-1">Profession System <a class="header-anchor" href="#profession-system" aria-label="Permalink to &quot;Profession System&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; open questions are Unresolved. Existing Accepted rules referenced below retain their own scope. <strong>Implementation:</strong> this redesign is documentation only; no gameplay implementation is established by this batch. <strong>Availability:</strong> not established for the redesigned mechanics. <strong>Verification:</strong> source/documentation review, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/professions/overview.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a></p><h2 id="philosophy-and-scope" tabindex="-1">Philosophy and scope <a class="header-anchor" href="#philosophy-and-scope" aria-label="Permalink to &quot;Philosophy and scope&quot;">​</a></h2><p><strong>There are no crafter characters; there are characters who know crafts.</strong> The proposed system addresses workshop-only crafter alts by making professions useful within the same overall skill cap as other character capabilities. It does not prohibit alternate characters or require every profession to grant combat bonuses.</p><p>Crafting should contribute to ordinary adventuring, PvM, PvP where appropriate, survival, exploration, economy, material knowledge, maintenance and world interaction. A profession generally combines production, field utility, equipment/material affinity, justified combat or survival utility, knowledge, economy/reputation and discovery. Flat combat buffs cannot substitute for that identity.</p><p>This page owns craft-specific discovery, journals, knowledge sharing, production and commissions. <a href="/Syrolands-Public/game-design/characters/progression.html">Character progression</a>, <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">Skills &amp; Skillcap</a> and <a href="/Syrolands-Public/game-design/characters/techniques-and-specialization.html">Techniques &amp; Specialization</a> now own the shared character framework. Individual profession pages own their specific loops; <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">Itemization &amp; Craft Quality</a> owns quality for crafted and dropped objects. These are canonical homes for proposals, not newly Accepted mechanics or permission to implement them.</p><h2 id="skill-technique-profession-and-identity" tabindex="-1">Skill, technique, profession and identity <a class="header-anchor" href="#skill-technique-profession-and-identity" aria-label="Permalink to &quot;Skill, technique, profession and identity&quot;">​</a></h2><p>The shared <a href="/Syrolands-Public/game-design/characters/techniques-and-specialization.html#skill-learned-knowledge-and-identity">technique and identity hierarchy</a> now owns this Batch 01 principle: broad skill, concrete learned technique, practical profession path and individual world reputation. A capable carpenter does not automatically know <a href="/Syrolands-Public/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a>; rare craft knowledge remains separately learned.</p><h2 id="entry-skill-cap-and-progression" tabindex="-1">Entry, skill cap and progression <a class="header-anchor" href="#entry-skill-cap-and-progression" aria-label="Permalink to &quot;Entry, skill cap and progression&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">Skills &amp; Skillcap</a> owns the common cap, gain, capability bands and teacher direction. <a href="/Syrolands-Public/game-design/characters/character-creation.html">Character creation</a> owns starting competencies. These remain Proposed and do not change configuration.</p><p>Batch 02 refines the 80–90 gain band from Batch 01&#39;s “Slow” to <strong>“Very slow.”</strong> The latest proposal is centralized in the <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html#desired-skill-gain">gain table</a>; the preserved Batch 01 source retains its original wording. This is an explicit proposal revision, not Accepted balance. The existing section anchor remains valid.</p><h2 id="skill-knowledge-and-human-mastery" tabindex="-1">Skill, knowledge and human mastery <a class="header-anchor" href="#skill-knowledge-and-human-mastery" aria-label="Permalink to &quot;Skill, knowledge and human mastery&quot;">​</a></h2><p>The <a href="/Syrolands-Public/game-design/characters/progression.html#character-skill-knowledge-and-player-mastery">shared three-axis model</a> owns this principle: skill determines capability, knowledge determines possibility/information, and human mastery determines performance. Craft journals and learned processes apply that model; skill 100 does not complete them.</p><h2 id="character-journals-and-discovery" tabindex="-1">Character journals and discovery <a class="header-anchor" href="#character-journals-and-discovery" aria-label="Permalink to &quot;Character journals and discovery&quot;">​</a></h2><p>Knowledge should persist per character. Candidate journals are:</p><table tabindex="0"><thead><tr><th>Profession</th><th>Knowledge record</th></tr></thead><tbody><tr><td>Cooking</td><td>Culinary Journal / Taste Codex</td></tr><tr><td>Alchemy</td><td>Alchemical Journal</td></tr><tr><td>Mining</td><td>Geological Journal</td></tr><tr><td>Blacksmithing</td><td>Metallurgical Journal</td></tr><tr><td>Tailoring</td><td>Material/Tailoring Journal</td></tr><tr><td>Lumberjacking</td><td>Forester&#39;s Journal</td></tr><tr><td>Carpentry</td><td>Woodworker&#39;s Journal</td></tr><tr><td>Tinkering</td><td>Mechanist&#39;s Journal</td></tr></tbody></table><p>Exploration, experimentation, teachers, books/manuscripts, quests/challenges, guilds/academies, reverse engineering, unusual materials, observed outcomes and other players where allowed can contribute knowledge. Prefer <strong>observations → understanding → learned technique/formula</strong> over a stream of recipe-unlock popups. What is shareable and which steps require personal experience remain unresolved.</p><h2 id="sharing-knowledge-and-keeping-secrets" tabindex="-1">Sharing knowledge and keeping secrets <a class="header-anchor" href="#sharing-knowledge-and-keeping-secrets" aria-label="Permalink to &quot;Sharing knowledge and keeping secrets&quot;">​</a></h2><p><strong>Knowledge can be shared; mastery cannot be copied.</strong> External discussion and wikis are expected, not something to prevent. Stable world principles coexist with material variation, provenance and quality, effective process windows, qualitative/perceptual feedback, personal skill and learned techniques. A single published magic number should not reproduce every result.</p><p>Reverse engineering yields clues rather than complete formulas. Private procedures, unusual material sources, difficult consistency, partial teaching and rare techniques can sustain secrets. Avoid arbitrary per-character laws of physics. Small personal affinities or interpretive differences are optional future candidates only if justified; they are not the main anti-wiki mechanism.</p><h2 id="manual-discovery-and-batch-production" tabindex="-1">Manual discovery and batch production <a class="header-anchor" href="#manual-discovery-and-batch-production" aria-label="Permalink to &quot;Manual discovery and batch production&quot;">​</a></h2><p><strong>Manual execution establishes mastery; batch production converts mastery into economic scale.</strong> Discovery and practice should be interactive; economic production should not require repeating the same minigame hundreds of times.</p><p>A manually completed process at a station/session may establish a temporary or station-local production pattern. At sufficient skill, illustratively around <strong>30–50 depending on profession</strong>, a character can repeat known procedures in batches. This is not a permanent universal recipe unlock or an accepted threshold.</p><p>Batch production consumes real time and materials and requires the character to remain at the station or sufficiently engaged. Movement, combat, death or station loss can interrupt it. It must not be instant or a major skill-gain exploit. Preserve a reasonable quality-consistency envelope; do not randomly destroy individual units without justified cause.</p><p>Higher skill improves batch size, consistency, efficiency and access to more complex procedures. Practice/discovery and production can be distinct conceptual modes. Pattern lifetime, engagement, interrupted-material ownership, partial outputs, costs and skill-gain rules need explicit design before implementation.</p><h2 id="commissions-reputation-and-economy" tabindex="-1">Commissions, reputation and economy <a class="header-anchor" href="#commissions-reputation-and-economy" aria-label="Permalink to &quot;Commissions, reputation and economy&quot;">​</a></h2><p>Replace the spirit of Bulk Order Deeds with functional commissions/contracts. Potential issuers include artisan guilds, families, clans, factions, military groups, cities, nobles, merchants and eventually players.</p><p>A commission should specify needs rather than mandate an exact recipe where possible. For example, <strong>20 infantry breastplates</strong> might require medium weight or lighter, high blunt-trauma resistance, minimum durability and field suitability. This example is not a finalized item or armor formula.</p><p>Payment and reputation consider requirements met, materials, workmanship, consistency, relevant specialization and appropriate cost/weight limits. Reputation should be multidimensional and ideally emerge from actual products and long-term use, not a single star rating. A character could be known for durable field weapons, lightweight plate, high-trauma maces, luxury garments, reliable locks or efficient war bows. Maker marks and provenance may support this history.</p><p>Player commissions are a future objective. Contract adjudication, long-term attribution, reputation abuse, payment custody and dispute handling remain unresolved; no economy service or automatic payout design is selected here.</p><h2 id="performance-abstraction-and-authority" tabindex="-1">Performance, abstraction and authority <a class="header-anchor" href="#performance-abstraction-and-authority" aria-label="Permalink to &quot;Performance, abstraction and authority&quot;">​</a></h2><p><strong>Complex simulation underneath, simple decisions on top. Prefer compact persistent state + derived behavior.</strong> A variable should survive abstraction only if it creates meaningful decisions. Avoid dozens of stored floats per object, continuous passive-object ticking and detail with no player value. Prefer shared/regional environmental state, event-driven updates, lazy simulation and properties derived from material, species, quality, treatment or seed.</p><p>These are design constraints, not a selected schema or implementation algorithm. Follow the living-world architecture proposal, authority boundaries and persistence/lifecycle rules when separately designing implementation. Per-character journals, production patterns and item provenance need explicit save/lifecycle decisions; no schema migration is authorized by this document.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Profession example</th></tr></thead><tbody><tr><td>USER INTENT</td><td>Place an ingredient, attempt a forging operation, fell a tree, or request a batch</td></tr><tr><td>AUTHORITATIVE SERVER STATE</td><td>Validate knowledge, skill, resources, ownership, timing, interruption and actual outcome</td></tr><tr><td>SYNCHRONIZED STATE</td><td>Approved station state, progress, item results and permitted knowledge disclosures</td></tr><tr><td>CLIENT PRESENTATION</td><td>Station gump, drag/drop feedback, animation, sound and qualitative cues</td></tr></tbody></table><p>Drag/drop and animation do not decide completion, item quality, world collision or resource consumption. This preserves existing Accepted server authority without assigning new packets, classes or client assets.</p><h2 id="profession-specifications" tabindex="-1">Profession specifications <a class="header-anchor" href="#profession-specifications" aria-label="Permalink to &quot;Profession specifications&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/game-design/professions/cooking.html">Cooking</a></li><li><a href="/Syrolands-Public/game-design/professions/alchemy.html">Alchemy</a></li><li><a href="/Syrolands-Public/game-design/professions/mining.html">Mining</a></li><li><a href="/Syrolands-Public/game-design/professions/blacksmithing.html">Blacksmithing</a></li><li><a href="/Syrolands-Public/game-design/professions/tailoring.html">Tailoring</a></li><li><a href="/Syrolands-Public/game-design/professions/lumberjacking.html">Lumberjacking</a></li><li><a href="/Syrolands-Public/game-design/professions/carpentry.html">Carpentry</a></li><li><a href="/Syrolands-Public/game-design/professions/tinkering.html">Tinkering</a></li><li><a href="/Syrolands-Public/game-design/professions/inscription.html">Inscription</a></li></ul><h2 id="open-questions-and-reconciliation-required" tabindex="-1">Open questions and reconciliation required <a class="header-anchor" href="#open-questions-and-reconciliation-required" aria-label="Permalink to &quot;Open questions and reconciliation required&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Existing source and reconciliation boundary</th></tr></thead><tbody><tr><td>Skill roster / Bowcraft</td><td><a href="/Syrolands-Public/game-design/skills-and-knowledge.html">Skills and knowledge</a> is a role summary, not a reconciled exhaustive roster. No standalone Bowcraft removal, skill-ID conversion, character migration or training compensation is performed. Bowmaking is a strong Proposed technique direction pending that reconciliation.</td></tr><tr><td>Adjacent disciplines</td><td><a href="/Syrolands-Public/game-design/living-world.html#knowledge-professions-and-traces">Living world</a> previously floated Forestry, Engineering and Geology as possible new skills. This batch places that expertise inside Lumberjacking, Tinkering and Mining. Do not infer three new skills; explicitly reconcile the eventual roster.</td></tr><tr><td>Progression and magic</td><td><a href="/Syrolands-Public/game-design/magic.html#use-based-gain-and-structured-teaching">Magic progression</a> includes illustrative +5 training blocks and first-day pacing; its near-capability spell failure model is not silently replaced by consistent simple craft work. Reconcile global pacing, starting competency and profession-specific difficulty before choosing formulas. Magery Mastery and Concentration are not automatically new capped skills.</td></tr><tr><td>Anatomy and Healing</td><td>Preserve the <a href="/Syrolands-Public/game-design/skills-and-knowledge.html">approved Stage 2A Anatomy rule</a>. Proposed material harvesting, pain relief, bleeding and healing interactions neither alter that rule nor establish implemented injuries. Coordination with Healing remains open.</td></tr><tr><td>Equipment and loss</td><td><a href="/Syrolands-Public/game-design/equipment-and-loot.html">Equipment and loot</a> favors replaceable horizontal gear and meaningful loss. Rare masterworks/sets must fit this constraint; sacred/resonant sets do not approve Sacred Item retention, broad insurance or spellbook-protection policy.</td></tr><tr><td>Combat formulas</td><td><a href="/Syrolands-Public/game-design/combat/damage.html">Damage and Local Trauma</a> owns the experimental residual ×2 policy. New quality dimensions, armor thresholds, functional wear and traits cannot silently change it. See <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html#open-questions-and-reconciliation">quality reconciliation</a>.</td></tr><tr><td>Mutable world</td><td><a href="/Syrolands-Public/game-design/living-world.html#terrain-and-authored-geology">Authored geology</a> bounds excavation; this batch does not authorize unrestricted digging. Protection, recovery, bridges, fallen-tree footprints, structural damage and housing access remain unresolved; the first tree/grass prototype scope is unchanged.</td></tr></tbody></table><p>Shared <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html#reconciliation-and-open-questions">skill/teaching questions</a>, <a href="/Syrolands-Public/game-design/characters/character-creation.html#open-questions">creation questions</a> and <a href="/Syrolands-Public/game-design/characters/techniques-and-specialization.html#open-questions">technique custody</a> are centralized under Characters. Profession-specific open questions remain: journal representation; station ownership and batch cancellation; reputation manipulation; contract verification; economic sinks and production balance. These are documentation-identified gaps, not added mechanics.</p><h2 id="related-decisions-experiments-and-evidence" tabindex="-1">Related decisions, experiments and evidence <a class="header-anchor" href="#related-decisions-experiments-and-evidence" aria-label="Permalink to &quot;Related decisions, experiments and evidence&quot;">​</a></h2><p>Accepted server authority, Lab-first decision, existing localized combat experiment, and current slice evidence retain their scopes. No profession experiment has been run and no new ADR is declared Accepted. The proposal does not establish implemented gameplay.</p>',43)])])}const u=a(r,[["render",s]]);export{m as __pageData,u as default};
